import java.util.*;

public class Main {
    static int n, mod;
    static Map<Integer, Integer>[][] cacheMemo;
    static final int MAX_N = 50; // Adjust if needed based on problem constraints

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        mod = sc.nextInt();

        cacheMemo = new HashMap[2][n + 1];
        for (int i = 0; i < 2; i++) {
            for (int j = 0; j <= n; j++) {
                cacheMemo[i][j] = new HashMap<>();
            }
        }

        int answer = solve(n, 0, true) % mod;
        System.out.println(answer);
        sc.close();
    }

    static int invnum(int[] sequence) {
        int count = 0;
        for (int i = 0; i < sequence.length; i++) {
            for (int j = i + 1; j < sequence.length; j++) {
                if (sequence[i] > sequence[j]) {
                    count++;
                }
            }
        }
        return count;
    }

    static long solve(int N, int K, boolean flag) {
        Map<Integer, Integer> cache = cacheMemo[flag ? 1 : 0][N];
        if (cache.containsKey(K)) {
            return cache.get(K);
        }
        if (N == 1) {
            long res = (flag ? 0 : (K < 0 ? 1 : 0));
            cache.put(K, (int) res);
            return res;
        }
        int maxInv = N * (N - 1) / 2;
        if (K < -maxInv - 1) {
            long res = solve(N, -maxInv - 1, flag);
            cache.put(K, (int) res);
            return res;
        }
        if (K >= maxInv) {
            cache.put(K, 0);
            return 0;
        }
        long total = 0;
        for (int delta = -N + 1; delta < N; delta++) {
            if (flag && delta > 0) continue;
            int weight = Math.min(N - delta, delta + N);
            total += solve(N - 1, K - delta, flag && delta == 0) * weight;
            total %= mod;
        }
        cache.put(K, (int) total);
        return total;
    }
}
